# System.Runtime.Intrinsics.X86.Avx2 — gathers. Each result lane is read at base + index ×
# scale; the index vector is 32- or 64-bit lanes and may be wider or narrower than the result.
# The scale is an immediate the hardware encodes as 1, 2, 4 or 8, and .NET throws
# ArgumentOutOfRangeException for any other value, so the helpers dispatch over that list. The
# Mask forms read a lane only where the mask lane's sign bit is set and take the source lane
# otherwise. The 64-bit element pointers are cast because the intrinsic spells them long long.
target = avx2
GatherVector128(pi32,v128i32,u8) @imm{1,2,4,8} = _mm_i32gather_epi32((const int*)$0, $1, $2)
GatherVector128(pu32,v128i32,u8) @imm{1,2,4,8} = _mm_i32gather_epi32((const int*)$0, $1, $2)
GatherVector128(pi64,v128i32,u8) @imm{1,2,4,8} = _mm_i32gather_epi64((const long long*)$0, $1, $2)
GatherVector128(pu64,v128i32,u8) @imm{1,2,4,8} = _mm_i32gather_epi64((const long long*)$0, $1, $2)
GatherVector128(pf32,v128i32,u8) @imm{1,2,4,8} = _mm_i32gather_ps($0, $1, $2)
